<?php require_once __DIR__.'/_header.php'; $id=(int)($_GET['id']??0);$st=db()->prepare('SELECT v.title,t.token FROM videos v JOIN embed_tokens t ON t.video_id=v.id AND t.status=1 WHERE v.id=? LIMIT 1');$st->execute([$id]);$x=$st->fetch();if(!$x)exit('No active embed token');$src=app_url('embed/index.php?token='.$x['token']);$code='<iframe src="'.$src.'" width="100%" height="500" frameborder="0" allow="autoplay; fullscreen; picture-in-picture" allowfullscreen></iframe>';?><h1>Embed: <?=e($x['title'])?></h1><div class="card"><textarea rows="6" readonly><?=e($code)?></textarea><p><a class="button" href="<?=e($src)?>" target="_blank">Preview Player</a></p></div><?php require __DIR__.'/_footer.php';